import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// Copies the English docs into this package as `docs/`, so every project gets
// version-matched offline docs for AI coding agents (see AGENTS.md generated by
// @modern-js/create).
//
// The source is the documentation site's *build output* (packages/document/
// doc_build), not the MDX sources. Rspress renders components and inlines
// shared fragments at build time, so the build output is self-contained
// Markdown an agent can read directly — the MDX sources are not: a quarter of
// the pages get their actual content from components whose data never ships
// with the package.
//
// Runs as part of `build` (see package.json build script + nx build inputs and
// outputs), so the bundle is produced whenever the package is built — including
// in CI/release where publish runs with `--ignore-scripts` and prepublishOnly
// would be skipped. The directory is gitignored, so it only materializes as a
// build output, never committed to the working tree.
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const pkgRoot = path.resolve(__dirname, '..');
const source = path.resolve(pkgRoot, '../../document/doc_build');
const target = path.resolve(pkgRoot, 'docs');

// The docs site also emits HTML, assets and a `zh` tree; agents only need the
// English Markdown plus llms.txt as an index. llms-full.txt is a concatenation
// of the same pages, so it would only duplicate what we already ship.
const INDEX_FILE = 'llms.txt';

if (!fs.existsSync(source)) {
  // Not fatal: the docs site is excluded from most builds, and blocking every
  // app-tools build on it would slow day-to-day work down for no reason. The
  // release path builds the docs first, and check-doc-bundle.mjs fails loudly
  // if a tarball ends up without them.
  console.warn(`[copy-main-doc] docs build output not found: ${source}`);
  console.warn(
    '[copy-main-doc] skipping the bundled docs — run `pnpm build:docs` first if you need them',
  );
  process.exit(0);
}

fs.rmSync(target, { recursive: true, force: true });

const isBundled = rel =>
  rel === INDEX_FILE ||
  (rel.endsWith('.md') && !rel.startsWith(`zh${path.sep}`));

let count = 0;
for (const entry of fs.readdirSync(source, {
  recursive: true,
  withFileTypes: true,
})) {
  if (!entry.isFile()) {
    continue;
  }
  const from = path.join(entry.parentPath ?? entry.path, entry.name);
  const rel = path.relative(source, from);
  if (!isBundled(rel)) {
    continue;
  }
  const to = path.join(target, rel);
  fs.mkdirSync(path.dirname(to), { recursive: true });
  fs.copyFileSync(from, to);
  count++;
}

if (count === 0) {
  console.error(`[copy-main-doc] no files copied from ${source}`);
  process.exit(1);
}
console.log(`[copy-main-doc] bundled ${count} doc files into docs`);
